// Luma MVP - autogenerated by Cursor
import SwiftUI
import WebKit
import AppKit
import Combine
import UniformTypeIdentifiers

/// Holds address bar suggestion selection for keyboard (Up/Down/Enter) and autofill.
private final class AddressBarKeyState: ObservableObject {
    @Published var selectedIndex: Int = 0
    @Published var totalCount: Int = 0
    @Published var visible: Bool = false
    @Published var submitSelection: Bool = false
}

/// Minimal browser shell hosting WKWebViews via WebViewWrapper and TabManager.
///
/// Per SRS: WebKit-only renderer, minimal tab UI, address bar.
/// Omnibox: accepts full URL, domain, or search query.
/// Per SECURITY.md: No JS message handlers, no HTML scraping.
struct BrowserShellView: View {
    // MARK: - Profile state
    @ObservedObject private var profileManager = ProfileManager.shared
    @AppStorage("luma_search_suggestions_enabled") private var searchSuggestionsEnabled: Bool = false
    @StateObject private var sessionStore: BrowserSessionStore

    private var session: ProfileSession { sessionStore.activeSession }
    private var tabManager: TabManager { session.tabManager }
    private var web: WebViewWrapper { session.webViewWrapper }
    private var historyManager: HistoryManager { session.historyManager }
    private var activeProfile: BrowserProfile { profileManager.profile(for: sessionStore.activeProfileId) }

    /// nil for the main window; extra windows save their own workspace.
    private let windowId: UUID?
    /// A tab dragged here from another window, taken in on appear.
    @State private var pendingTransfer: TabTransfer?

    init(initialProfileId: UUID? = nil, windowId: UUID? = nil, adopting transfer: TabTransfer? = nil) {
        self.windowId = windowId
        _pendingTransfer = State(initialValue: transfer)
        _sessionStore = StateObject(wrappedValue: BrowserSessionStore(initialProfileId: initialProfileId, windowId: windowId))
    }

    @State private var addressBarText: String = ""
    @State private var tabsWithPanelOpen: Set<UUID> = []
    @State private var aiPanelWidth: CGFloat = 380
    @State private var shouldResetPanelWidth: Bool = false
    @State private var isDraggingDivider: Bool = false
    @State private var eventMonitor: Any?
    @State private var scrollMonitor: Any?
    /// Clicks inside a split pane focus that pane (and still reach the page).
    @State private var paneClickMonitor: Any?
    @State private var paneFrames: [UUID: CGRect] = [:]
    /// Horizontal trackpad travel over the chrome in the current gesture (profile swipe).
    @State private var swipeTravel: CGFloat = 0
    @State private var swipeConsumed = false
    /// Brief name badge after switching profiles.
    @State private var profileToast: BrowserProfile?
    @State private var showBrowserImport = false
    @State private var pendingAction: BrowserAction? = nil
    @State private var pendingAssistantText: String = ""
    @State private var showActionConfirm: Bool = false
    @State private var restoreAddressBarOnEscape: Bool = false
    @State private var isFirstLoad: Bool = true
    @FocusState private var addressBarFocused: Bool
    @State private var searchSuggestions: [String] = []
    @State private var urlSuggestions: [AddressSuggestion] = []
    @StateObject private var addressBarKeyState = AddressBarKeyState()
    @State private var suggestionDebounceTask: DispatchWorkItem?
    /// Set while arrow keys write the selected suggestion into the field, so that edit doesn't refetch.
    @State private var suppressSuggestionFetch = false
    @State private var showGoogleAPIKeyHelpSheet: Bool = false
    @State private var showBrowserFindBar: Bool = false
    @State private var browserFindQuery: String = ""
    /// Luna Max "Ask on Page" card for the current tab.
    @State private var askOnPageVisible: Bool = false
    @State private var downloadIconScale: CGFloat = 1
    @State private var isFullScreen: Bool = false
    @State private var hostWindow: NSWindow?

    // Layout
    @AppStorage(BrowserLayout.defaultsKey) private var layoutRaw: String = BrowserLayout.sidebar.rawValue
    @AppStorage("luna_sidebar_visible") private var sidebarVisible: Bool = true
    @AppStorage("luna_sidebar_width") private var sidebarWidth: Double = 240
    /// Sidebar temporarily shown over the content while it's hidden (hover at the left edge).
    @State private var sidebarPeeking: Bool = false

    private let router = CommandRouter()
    private let gemini = GeminiClient(apiKeyProvider: { KeychainManager.shared.fetchGeminiKey() })
    private let ollama = OllamaClient()

    // Chrome options (Settings → Appearance)
    @AppStorage(ChromePrefs.frameless) private var frameless = false
    @AppStorage(ChromePrefs.alwaysShowTopBar) private var alwaysShowTopBar = false
    @AppStorage(ChromePrefs.roundedFrame) private var roundedFrame = true
    @AppStorage(ChromePrefs.hideWindowButtons) private var hideWindowButtons = true
    @AppStorage(ChromePrefs.showToolbar) private var showToolbar = false
    @AppStorage(ChromePrefs.showBookmarksBar) private var showBookmarksBar = false
    @AppStorage(LayoutTemplate.defaultsKey) private var templateRaw: String = LayoutTemplate.luna.rawValue
    @Environment(\.colorScheme) private var colorScheme
    /// Top bar temporarily shown in frameless mode (hover at the top edge, or ⌘L).
    @State private var topBarPeeking = false
    /// Window buttons shown because the pointer is at the top edge (sidebar hidden).
    @State private var windowButtonsPeeking = false
    /// Pointer is over the revealed top bar.
    @State private var topBarHovering = false

    var body: some View {
        ZStack {
            LunaBackdrop(material: usesSidebar ? .sidebar : .titlebar, state: .followsWindowActiveState)
                .ignoresSafeArea()
            // The window chrome carries a hue of the active profile's color.
            activeProfile.profileColor.color
                .opacity(0.14)
                .ignoresSafeArea()
                .animation(.easeInOut(duration: 0.3), value: activeProfile.colorId)

            TitlebarConfigurator(tabStripHeight: 0, isFullScreen: $isFullScreen, hostWindow: $hostWindow)
            TrafficLightPositioner(enabled: chromeTemplate && !isFullScreen)
                .frame(width: 0, height: 0)

            GeometryReader { geometry in
              VStack(spacing: 0) {
                // Chrome template: tab strip, toolbar and bookmarks bar span the window, the AI panel sits below them.
                if chromeTemplate {
                    topChrome(showsTabs: true)
                    if showBookmarksBar { bookmarksBar }
                }
                HStack(spacing: 0) {
                    // Main browser content; the sliding sidebar sits over this padding when docked.
                    VStack(spacing: 0) {
                        if chromeTemplate {
                            EmptyView()
                        } else if showsTopChrome {
                            topChrome(showsTabs: !frameless && !usesSidebar)
                        } else if addressBarPeeks {
                            peekingTopBar
                        }
                        if showBookmarksBar && !chromeTemplate {
                            bookmarksBar
                        }
                        framedContent
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .padding(.leading, sidebarShown ? sidebarWidth : 0)
                    .animation(Self.chromeAnimation, value: topBarPeeking)
                    .animation(.easeInOut(duration: 0.08), value: tabManager.currentTab)

                    // ─── AI side panel (hidden on start page and AI chat) ────────
                    if let currentId = tabManager.currentTab, tabsWithPanelOpen.contains(panelKey(for: currentId)), !isCurrentTabStartOrAIChat {
                        aiPanel(for: currentId, windowWidth: geometry.size.width)
                            .background(chromeTemplate ? ChromePalette.for(colorScheme).toolbar : Color.clear)
                    }
                }
                .overlay(alignment: .leading) {
                    if usesSidebar || edgeTabListEnabled { slidingSidebar }
                }
                .overlay(alignment: .leading) {
                    // Thin hot zone at the left edge reveals a hidden sidebar.
                    if edgeTabListEnabled && !sidebarPeeking {
                        Color.clear
                            .frame(width: 8)
                            .frame(maxHeight: .infinity)
                            .contentShape(Rectangle())
                            .onHover { if $0 { sidebarPeeking = true } }
                    }
                }
                .animation(Self.chromeAnimation, value: sidebarState)
              }
            }
        }
        .ignoresSafeArea(.container, edges: .top)
        .environment(\.lunaMenuFlavor, chromeTemplate ? .chrome : .luna)
        .overlayPreferenceValue(AddressFieldAnchorKey.self) { anchor in
            suggestionsOverlay(anchor: anchor)
        }
        .overlay(alignment: .top) {
            if addressBarPeeks {
                // Hover the top edge to bring the bar down — only while no sidebar is out.
                if !topBarPeeking && sidebarState == .hidden {
                    Color.clear
                        .frame(height: 6)
                        .frame(maxWidth: .infinity)
                        .contentShape(Rectangle())
                        .onHover { if $0 { topBarPeeking = true } }
                        .ignoresSafeArea(.container, edges: .top)
                }
            } else if trafficLightsHidden || windowButtonsPeeking {
                windowButtonsHotZone.ignoresSafeArea(.container, edges: .top)
            }
        }
        .overlay(alignment: .top) {
            if let profile = profileToast {
                HStack(spacing: 8) {
                    Image(nsImage: ProfileAvatar.image(for: profile, size: 20))
                    Text(profile.name).font(.system(size: 13, weight: .semibold))
                }
                .padding(.horizontal, 14)
                .padding(.vertical, 8)
                .background(LunaMaterialFill(shape: Capsule()))
                .overlay(Capsule().strokeBorder(profile.profileColor.color.opacity(0.5), lineWidth: 1))
                .shadow(color: .black.opacity(0.2), radius: 10, y: 4)
                .padding(.top, 14)
                .transition(.move(edge: .top).combined(with: .opacity))
                .allowsHitTesting(false)
            }
        }
        .focusedSceneValue(\.showBrowserImport, { showBrowserImport = true })
        .sheet(isPresented: $showBrowserImport) {
            BrowserImportView(profileId: sessionStore.activeProfileId) { showBrowserImport = false }
                .frame(width: 560, height: 640)
        }
        .focusedSceneValue(\.profileCommands, ProfileCommandContext(
            activeProfileId: sessionStore.activeProfileId,
            switchTo: switchToProfile,
            openInNewWindow: openProfileInNewWindow
        ))
        .alert("Confirm Action", isPresented: $showActionConfirm) {
            Button("Cancel", role: .cancel) { pendingAction = nil }
            Button("Execute") { executePendingAction() }
        } message: {
            if let action = pendingAction {
                let typeText = action.type.rawValue
                let payloadSummary = action.payload?
                    .sorted { $0.key < $1.key }
                    .map { "\($0.key): \($0.value)" }
                    .joined(separator: "\n") ?? "none"
                Text("Assistant: \(pendingAssistantText)\n\nAction: \(typeText)\n\(payloadSummary)")
            } else {
                Text("No action to execute.")
            }
        }
        .onAppear {
            #if DEBUG
            // Space-separated URLs: the first loads in the current tab, the rest in new tabs.
            if let raw = ProcessInfo.processInfo.environment["LUNA_SNAPSHOT_TABS"] {
                let urls = raw.split(separator: " ").compactMap { URL(string: String($0)) }
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
                    guard let first = urls.first else { return }
                    // Side-by-side captures: start from just these tabs.
                    if ProcessInfo.processInfo.environment["LUNA_SNAPSHOT_ONLY_TABS"] != nil, let keep = tabManager.currentTab {
                        for id in session.workspace.orderedTabIds where id != keep { closeTab(id) }
                    }
                    navigateToURL(first)
                    let firstId = tabManager.currentTab
                    urls.dropFirst().forEach { newTabWithURL($0) }
                    if let firstId { switchToTab(firstId) }
                }
            }
            // "Title|URL" entries separated by spaces, in a throwaway bookmarks store.
            if let raw = ProcessInfo.processInfo.environment["LUNA_SNAPSHOT_BOOKMARKS"] {
                let entries = raw.split(separator: " ").map { $0.split(separator: "|", maxSplits: 1).map(String.init) }
                BookmarkStore.useSnapshotStore(for: session.profileId, urls: entries.compactMap { $0.last.flatMap(URL.init(string:)) })
                for entry in entries where entry.count == 2 {
                    if let url = URL(string: entry[1]), let mark = bookmarks.bookmarks.first(where: { $0.url == url }) {
                        bookmarks.rename(mark.id, to: entry[0].replacingOccurrences(of: "_", with: " "))
                    }
                }
            }
            // "WxH": resize the window (content size) for side-by-side captures.
            if let raw = ProcessInfo.processInfo.environment["LUNA_SNAPSHOT_WINDOW_SIZE"] {
                let parts = raw.split(separator: "x").compactMap { Double($0) }
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                    guard parts.count == 2, let window = hostWindow else { return }
                    window.setFrame(NSRect(x: 60, y: 60, width: parts[0], height: parts[1]), display: true)
                }
            }
            if let raw = ProcessInfo.processInfo.environment["LUNA_SNAPSHOT_URL"], let url = URL(string: raw) {
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { navigateToURL(url) }
            }
            if let raw = ProcessInfo.processInfo.environment["LUNA_SNAPSHOT_SPLIT_URL"], let url = URL(string: raw) {
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                    let first = tabManager.currentTab
                    newTabWithURL(url)
                    if let first, let second = tabManager.currentTab { session.workspace.splitTab(second, onto: first) }
                }
                if ProcessInfo.processInfo.environment["LUNA_SNAPSHOT_SPLIT_CLOSE"] != nil {
                    DispatchQueue.main.asyncAfter(deadline: .now() + 3) {
                        if let id = tabManager.currentTab { closeTab(id) }
                    }
                }
            }
            if ProcessInfo.processInfo.environment["LUNA_SNAPSHOT_AI_PANEL"] != nil {
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) { toggleAIPanel() }
            }
            if ProcessInfo.processInfo.environment["LUNA_SNAPSHOT_TOP_BAR"] != nil {
                Timer.scheduledTimer(withTimeInterval: 2.5, repeats: true) { _ in topBarPeeking.toggle() }
            }
            #endif
            web.tabManager = tabManager
            if let transfer = pendingTransfer {
                pendingTransfer = nil
                adoptTransfer(transfer, replacingPlaceholder: true)
            }
            if windowId == nil {
                // The main window brings back the extra windows open at last quit.
                DispatchQueue.main.async { BrowserWindows.restoreSaved() }
            }
            if tabManager.currentTab == nil {
                _ = tabManager.newTab(url: nil)
                if let id = tabManager.currentTab {
                    web.setActiveTab(id)
                    addressBarText = ""
                }
            }
            if scrollMonitor == nil {
                scrollMonitor = NSEvent.addLocalMonitorForEvents(matching: .scrollWheel) { event in
                    handleProfileSwipe(event) ? nil : event
                }
            }
            if paneClickMonitor == nil {
                paneClickMonitor = NSEvent.addLocalMonitorForEvents(matching: [.leftMouseDown, .rightMouseDown]) { event in
                    guard let host = hostWindow, event.window === host, let content = host.contentView else { return event }
                    let p = event.locationInWindow
                    let point = CGPoint(x: p.x, y: content.bounds.height - p.y)
                    if let pane = paneFrames.first(where: { $0.value.contains(point) })?.key, pane != tabManager.currentTab {
                        DispatchQueue.main.async { switchToTab(pane) }
                    }
                    return event
                }
            }
            guard eventMonitor == nil else { return }
            eventMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { event in
                // Only handle shortcuts for this browser window. Prevents double-handling when
                // multiple windows are open, and keeps sheets/settings windows working normally.
                guard let host = hostWindow, event.window === host else { return event }
                if let handled = handleShortcut(event, in: host) { return handled ? nil : event }
                // Dev mode's raw terminal owns plain keys while focused: Esc, arrows and Return go to
                // the CLI (a stale address-bar focus flag used to swallow Esc there).
                if DevTerminalView.hasKeyboardFocus(in: host) { return event }
                // Address bar suggestions: Down/Up/Enter when dropdown is visible (keyboard selection + autofill)
                if addressBarKeyState.visible {
                    if event.keyCode == 125 { // Down
                        DispatchQueue.main.async {
                            // max(0, …) prevents -1 when suggestions are momentarily empty.
                            addressBarKeyState.selectedIndex = min(addressBarKeyState.selectedIndex + 1, max(0, addressBarKeyState.totalCount - 1))
                        }
                        return nil
                    }
                    if event.keyCode == 126 { // Up
                        DispatchQueue.main.async {
                            addressBarKeyState.selectedIndex = max(0, addressBarKeyState.selectedIndex - 1)
                        }
                        return nil
                    }
                    if event.keyCode == 36 { // Return
                        DispatchQueue.main.async { addressBarKeyState.submitSelection = true }
                        return nil
                    }
                }
                if event.keyCode == 53 { // Escape
                    if showBrowserFindBar {
                        DispatchQueue.main.async {
                            showBrowserFindBar = false
                            browserFindQuery = ""
                            if let id = tabManager.currentTab { web.clearFind(in: id) }
                        }
                        return nil
                    }
                    if addressBarFocused {
                        DispatchQueue.main.async { restoreAddressBarOnEscape = true }
                        return nil
                    }
                    // Let Escape reach web content (exit fullscreen video, close site dialogs, etc).
                    return event
                }
                return event
            }
        }
        .onChange(of: trafficLightsHidden, initial: true) { _, _ in applyTrafficLights() }
        .onChange(of: windowButtonsPeeking) { _, _ in applyTrafficLights() }
        // The top bar and the sidebar never show at the same time.
        .onChange(of: sidebarPeeking) { _, peeking in
            if peeking { topBarPeeking = false }
        }
        .onChange(of: addressBarFocused) { _, focused in
            // ⌘L-revealed bar tucks away once editing ends, unless the pointer is on it.
            if !focused && !topBarHovering { topBarPeeking = false }
            if !focused {
                suggestionDebounceTask?.cancel()
                searchSuggestions = []
                urlSuggestions = []
                addressBarKeyState.visible = false
            }
        }
        .onChange(of: hostWindow) { _, window in
            applyTrafficLights()
            // Other windows can drop tabs into this one.
            if let window {
                // Agent tools (MCP bridge) drive the front-most browser window.
                LunaBrowserHosts.shared.register(window: window) { sessionStore.activeSession }
                BrowserCommandTargets.shared.register(window: window, actions: commandActions)
                TabDropTargets.shared.register(.init(
                    window: window,
                    profileId: { sessionStore.activeProfileId },
                    adopt: { adoptTransfer($0, replacingPlaceholder: true, droppedAt: $1) }
                ))
            }
        }
        .onChange(of: tabManager.currentTab) { _, _ in
            askOnPageVisible = false
            web.linkPreview = nil
        }
        .onChange(of: tabManager.currentTab) { _, newId in
            if let id = newId {
                web.setActiveTab(id)
                syncAddressBarFromCurrentTab()
            } else {
                addressBarText = ""
            }
        }
        .onChange(of: web.currentURL) { _, _ in
            syncAddressBarFromCurrentTab()
            if web.currentURL != nil { isFirstLoad = false }
        }
        .onChange(of: profileManager.profiles) { _, profiles in
            let validIds = Set(profiles.map(\.id))
            // Tear down sessions for any deleted profiles, including inactive ones.
            sessionStore.pruneSessions(keeping: validIds)
            guard !validIds.contains(sessionStore.activeProfileId) else { return }
            let deletedId = sessionStore.activeProfileId
            sessionStore.removeSession(profileId: deletedId)
            sessionStore.switchTo(profileId: profileManager.lastActiveProfileId)
            tabsWithPanelOpen = []
            syncAddressBarFromCurrentTab()
        }
        .onChange(of: restoreAddressBarOnEscape) { _, new in
            if new {
                syncAddressBarFromCurrentTab()
                addressBarFocused = false
                restoreAddressBarOnEscape = false
            }
        }
        .onChange(of: addressBarKeyState.selectedIndex) { _, newValue in
            guard addressBarKeyState.visible else { return }
            let h = urlSuggestions.count
            let total = h + searchSuggestions.count
            guard newValue >= 0, newValue < total else { return }
            let text = newValue < h ? urlSuggestions[newValue].url.absoluteString : searchSuggestions[newValue - h]
            if text != addressBarText {
                suppressSuggestionFetch = true
                addressBarText = text
            }
        }
        .onChange(of: addressBarText) { _, newValue in
            if suppressSuggestionFetch { suppressSuggestionFetch = false; return }
            guard addressBarFocused else { return }
            scheduleSuggestions(for: newValue)
        }
        .onChange(of: addressBarKeyState.submitSelection) { _, new in
            if new {
                applySelectionAtIndex(addressBarKeyState.selectedIndex)
                addressBarKeyState.submitSelection = false
            }
        }
        .onChange(of: urlSuggestions.count) { _, _ in
            if addressBarKeyState.visible {
                addressBarKeyState.totalCount = urlSuggestions.count + searchSuggestions.count
                addressBarKeyState.selectedIndex = min(addressBarKeyState.selectedIndex, max(0, addressBarKeyState.totalCount - 1))
            }
        }
        .onChange(of: searchSuggestions.count) { _, _ in
            if addressBarKeyState.visible {
                addressBarKeyState.totalCount = urlSuggestions.count + searchSuggestions.count
                addressBarKeyState.selectedIndex = min(addressBarKeyState.selectedIndex, max(0, addressBarKeyState.totalCount - 1))
            }
        }
        .onDisappear {
            sessionStore.flush()
            if let m = eventMonitor {
                NSEvent.removeMonitor(m)
                eventMonitor = nil
            }
            if let m = scrollMonitor {
                NSEvent.removeMonitor(m)
                scrollMonitor = nil
            }
            if let m = paneClickMonitor {
                NSEvent.removeMonitor(m)
                paneClickMonitor = nil
            }
        }
    }

    // MARK: - Shortcuts

    /// Window shortcuts the menu bar can't own (focus-, repeat- or tab-dependent; menu items own
    /// the rest, see BrowserCommands), matched on the exact modifier set so ⌃⌘F still reaches
    /// full screen and ⌘⇧T reaches Reopen Closed Tab. Returns nil for other keys, true to
    /// swallow the key, false to let it through.
    private func handleShortcut(_ event: NSEvent, in host: NSWindow) -> Bool? {
        let mods = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
            .subtracting([.capsLock, .numericPad, .function])
        let key = (event.charactersIgnoringModifiers ?? "").lowercased()
        let code = event.keyCode
        let isLeft = code == 123, isRight = code == 124

        // Tab cycling: ⌃Tab / ⌃⇧Tab, ⌘⌥← / ⌘⌥→, ⌘⇧[ / ⌘⇧].
        if code == 48, mods == .control || mods == [.control, .shift] {
            DispatchQueue.main.async { cycleTab(by: mods.contains(.shift) ? -1 : 1) }
            return true
        }
        if mods == [.command, .option], isLeft || isRight {
            DispatchQueue.main.async { cycleTab(by: isLeft ? -1 : 1) }
            return true
        }
        if mods == [.command, .shift], code == 33 || code == 30 {
            DispatchQueue.main.async { cycleTab(by: code == 33 ? -1 : 1) }
            return true
        }
        guard mods == .command || mods == [.command, .shift] else { return nil }
        Self.recordShortcut(key, mods)
        let shift = mods.contains(.shift)

        // ⌘← / ⌘→: back / forward, unless the keys are moving a text cursor.
        if !shift, isLeft || isRight {
            if host.firstResponder is NSText || DevTerminalView.hasKeyboardFocus(in: host) { return false }
            guard let id = tabManager.currentTab else { return false }
            let go = { isLeft ? web.goBack(in: id) : web.goForward(in: id) }
            if Self.isInWebView(host.firstResponder) {
                // The page sees the key too; navigate only if it isn't focused on a text field.
                web.isEditingText(in: id) { editing in if !editing { go() } }
                return false
            }
            DispatchQueue.main.async { go() }
            return true
        }
        switch (key, shift) {
        case ("e", false):
            DispatchQueue.main.async { toggleAIPanel() }
        case ("s", false) where usesSidebar:
            DispatchQueue.main.async { toggleSidebar() }
        case ("l", false):
            DispatchQueue.main.async {
                if addressBarPeeks {
                    sidebarPeeking = false
                    topBarPeeking = true
                }
                addressBarFocused = true
            }
        case ("1"..."9", false):
            // ⌘1…⌘8 pick that tab; ⌘9 is always the last one.
            guard let idx = Int(key) else { return nil }
            DispatchQueue.main.async {
                let count = tabManager.tabCount()
                let target = idx == 9 ? count : idx
                if target >= 1, target <= count { tabManager.switchToTab(index: target - 1) }
            }
        case ("f", _):
            // Find in page (web tabs only; start page / AI chat handle it themselves).
            guard !isCurrentTabStartOrAIChat else { return false }
            // Luna Max: holding ⌘F (key repeat) or ⌘⇧F opens Ask on Page.
            if LunaMaxPrefs.isOn(LunaMaxPrefs.askOnPage), event.isARepeat || shift {
                DispatchQueue.main.async { openAskOnPage() }
                return true
            }
            guard !shift else { return nil }
            DispatchQueue.main.async {
                showBrowserFindBar.toggle()
                if !showBrowserFindBar {
                    browserFindQuery = ""
                    if let id = tabManager.currentTab {
                        web.clearFind(in: id)
                    }
                }
            }
        case ("g", _):
            // ⌘G / ⌘⇧G: next / previous match of the last find.
            guard !isCurrentTabStartOrAIChat, let id = tabManager.currentTab else { return false }
            DispatchQueue.main.async {
                if browserFindQuery.isEmpty { showBrowserFindBar = true; return }
                shift ? web.findPrevious(in: id) : web.findNext(in: id)
            }
        default:
            return nil
        }
        return true
    }

    private static func isInWebView(_ responder: NSResponder?) -> Bool {
        var view = responder as? NSView
        while let v = view {
            if v is WKWebView { return true }
            view = v.superview
        }
        return false
    }

    private func cycleTab(by offset: Int) {
        let order = tabManager.tabOrder
        guard order.count > 1, let i = tabManager.currentIndex() else { return }
        switchToTab(order[(i + offset % order.count + order.count) % order.count])
    }

    /// The menu bar's File / View / History / Bookmarks commands for this window.
    private var commandActions: BrowserCommandActions {
        BrowserCommandActions(
            profileId: { sessionStore.activeProfileId },
            newTab: { newTab() },
            reopenClosedTab: {
                if let id = session.workspace.reopenClosedTab() { switchToTab(id) }
            },
