    let onSelectURL: (AddressSuggestion) -> Void
    let onSelectSearch: (String) -> Void
    @State private var hoveredSection: String? = nil  // "h-0", "s-0", etc.

    private func isSelected(historyIndex: Int) -> Bool { selectedIndex == historyIndex }

    private func isSelected(searchIndex: Int) -> Bool { selectedIndex == urlItems.count + searchIndex }

    var body: some View {
        VStack(spacing: 0) {
            ForEach(Array(urlItems.enumerated()), id: \.offset) { index, item in
                let id = "h-\(index)"
                let selected = isSelected(historyIndex: index)
                Button(action: { onSelectURL(item) }) {
                    HStack {
                        Image(systemName: item.symbol)
                            .font(.system(size: 11))
                            .foregroundStyle(.secondary)
                            .frame(width: 20)
                        VStack(alignment: .leading, spacing: 2) {
                            Text(item.display)
                                .font(.system(size: 13))
                                .foregroundStyle(.primary)
                                .lineLimit(1)
                            if let host = item.url.host, host != item.display {
                                Text(host)
                                    .font(.system(size: 11))
                                    .foregroundStyle(.secondary)
                                    .lineLimit(1)
                            }
                        }
                        .frame(maxWidth: .infinity, alignment: .leading)
                        if case .openTab = item.kind {
                            Text("Switch to tab")
                                .font(.system(size: 11))
                                .foregroundStyle(.secondary)
                        }
                    }
                    .padding(.horizontal, 12)
                    .padding(.vertical, 8)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .contentShape(Rectangle())
                    .background(
                        RoundedRectangle(cornerRadius: 4)
                            .fill(selected || hoveredSection == id ? Color.primary.opacity(0.06) : Color.clear)
                    )
                    .onHover { hovering in hoveredSection = hovering ? id : nil }
                }
                .buttonStyle(.plain)
            }
            ForEach(Array(searchPhrases.enumerated()), id: \.offset) { index, phrase in
                let id = "s-\(index)"
                let selected = isSelected(searchIndex: index)
                Button(action: { onSelectSearch(phrase) }) {
                    HStack {
                        Image(systemName: "magnifyingglass")
                            .font(.system(size: 11))
                            .foregroundStyle(.secondary)
                            .frame(width: 20)
                        Text(phrase)
                            .font(.system(size: 13))
                            .foregroundStyle(.primary)
                            .lineLimit(1)
                            .frame(maxWidth: .infinity, alignment: .leading)
                    }
                    .padding(.horizontal, 12)
                    .padding(.vertical, 8)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .contentShape(Rectangle())
                    .background(
                        RoundedRectangle(cornerRadius: 4)
                            .fill(selected || hoveredSection == id ? Color.primary.opacity(0.06) : Color.clear)
                    )
                    .onHover { hovering in hoveredSection = hovering ? id : nil }
                }
                .buttonStyle(.plain)
            }
        }
    }
}

// MARK: - Panel resize handle

private struct PanelResizeHandle: View {
    @Binding var panelWidth: CGFloat
    let windowWidth: CGFloat
    @Binding var isDragging: Bool

    @State private var dragStartWidth: CGFloat? = nil
    @State private var isHovering: Bool = false

    private var minWidth: CGFloat { windowWidth / 10 }
    private var maxWidth: CGFloat { windowWidth / 2 }

    var body: some View {
        // Invisible, like the sidebar's edge: the cursor shows it's draggable.
        Color.clear
            .frame(width: 6)
            .contentShape(Rectangle())
            .onHover { hovering in
                isHovering = hovering
                if !isDragging {
                    if hovering { NSCursor.resizeLeftRight.push() }
                    else { NSCursor.pop() }
                }
            }
            .gesture(
                DragGesture(minimumDistance: 0) // local space is fine
                    .onChanged { value in
                        // Remember the width at drag start
                        if dragStartWidth == nil {
                            dragStartWidth = panelWidth
                            isDragging = true
                            NSCursor.resizeLeftRight.push()
                        }

                        // Panel on the RIGHT: drag right -> smaller, drag left -> bigger (opposite of cursor direction)
                        let base = dragStartWidth ?? panelWidth
                        let proposed = base - value.translation.width
                        let clamped = min(maxWidth, max(minWidth, proposed))

                        panelWidth = clamped
                    }
                    .onEnded { _ in
                        dragStartWidth = nil
                        isDragging = false
                        NSCursor.pop()
                        // Hover-exit during the drag was suppressed; balance its push
                        // now so the resize cursor doesn't stick after the drag ends.
                        if !isHovering { NSCursor.pop() }
                    }
            )
    }
}
// MARK: - NSViewRepresentables

/// Hosts a tab's long-lived WKWebView. The web view sits inside a plain
/// container instead of being the representable's own view, so it can move
/// between containers when a tab enters or leaves a split. A new container
/// takes the web view; an old one being torn down never takes it back.
struct WebViewContainer: NSViewRepresentable {
    let webView: WKWebView

    func makeNSView(context: Context) -> NSView {
        let host = NSView()
        attach(to: host)
        return host
    }

    func updateNSView(_ host: NSView, context: Context) {
        // Re-adopt only an orphaned web view: a container on its way out still
        // gets updates and must not steal the page back from its replacement.
        if webView.superview == nil { attach(to: host) }
    }

    static func dismantleNSView(_ host: NSView, coordinator: ()) {
        // Only detaches the web view if it still lives here.
        host.subviews.forEach { $0.removeFromSuperview() }
    }

    private func attach(to host: NSView) {
        guard webView.superview !== host else { return }
        webView.removeFromSuperview()
        webView.frame = host.bounds
        webView.autoresizingMask = [.width, .height]
        host.addSubview(webView)
    }
}

/// NSView that disallows window drag (returns false for mouseDownCanMoveWindow).
/// Used behind tabs so dragging a tab doesn't move the window.
private final class NonDraggableWindowNSView: NSView {
    override var mouseDownCanMoveWindow: Bool { false }
}

struct NonDraggableWindowView: NSViewRepresentable {
    func makeNSView(context: Context) -> NSView { NonDraggableWindowNSView() }
    func updateNSView(_ nsView: NSView, context: Context) {}
}

