private struct BrowserFindBar: View {
    @Binding var query: String
    let onFind: (String) -> Void
    let onNext: () -> Void
    let onPrevious: () -> Void
    let onDismiss: () -> Void
    @FocusState private var isFocused: Bool

    var body: some View {
        HStack(spacing: 8) {
            Image(systemName: "magnifyingglass")
                .font(.system(size: 12, weight: .medium))
                .foregroundColor(Color.white.opacity(0.5))
            TextField("Find in page\u{2026}", text: $query)
                .textFieldStyle(.plain)
                .font(.system(size: 13))
                .foregroundColor(Color.white.opacity(0.9))
                .focused($isFocused)
                .onSubmit { onFind(query) }
                .onChange(of: query) { _, newValue in
                    if !newValue.isEmpty { onFind(newValue) }
                }
            Button(action: onPrevious) {
                Image(systemName: "chevron.up")
                    .font(.system(size: 11, weight: .semibold))
                    .foregroundColor(Color.white.opacity(0.6))
                    .frame(width: 22, height: 22)
                    .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            Button(action: onNext) {
                Image(systemName: "chevron.down")
                    .font(.system(size: 11, weight: .semibold))
                    .foregroundColor(Color.white.opacity(0.6))
                    .frame(width: 22, height: 22)
                    .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            Button(action: onDismiss) {
                Image(systemName: "xmark")
                    .font(.system(size: 11, weight: .medium))
                    .foregroundColor(Color.white.opacity(0.6))
                    .frame(width: 22, height: 22)
                    .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
        }
        .padding(.horizontal, 14)
        .padding(.vertical, 8)
        .background(
            RoundedRectangle(cornerRadius: 10, style: .continuous)
                .fill(Color(white: 0.15))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 10, style: .continuous)
                .stroke(Color.white.opacity(0.12), lineWidth: 1)
        )
        .frame(maxWidth: 340)
        .padding(.trailing, 16)
        .padding(.top, 8)
        .frame(maxWidth: .infinity, alignment: .trailing)
        .onAppear { isFocused = true }
    }
}

private final class WindowDragRegionNSView: NSView {
    override var mouseDownCanMoveWindow: Bool { true }
    override func acceptsFirstMouse(for event: NSEvent?) -> Bool { true }

    /// Browser windows own their title bar (`TitlebarDragOwnership`), so AppKit
    /// no longer drags from here by itself: start the move, like Chromium's
    /// frame view does for caption areas.
    override func mouseDown(with event: NSEvent) {
        guard let window else { return }
        if event.clickCount == 2 {
            window.performTitlebarDoubleClickAction()
        } else {
            window.performDrag(with: event)
        }
    }
}

extension NSWindow {
    /// What double-clicking a title bar does, per System Settings (Chromium's
    /// `-[NativeWidgetMacNSWindow sendEvent:]` reads the same default).
    func performTitlebarDoubleClickAction() {
        switch UserDefaults.standard.string(forKey: "AppleActionOnDoubleClick") {
        case "Minimize": performMiniaturize(nil)
        case "None": break
        default: performZoom(nil)
        }
    }
}

/// Makes a browser window's content own its whole title-bar band, the way
/// Chromium's `BridgedContentView` does: its `_opaqueRectForWindowMoveWhenInTitlebar`
/// (undocumented AppKit) returns the view's bounds, so the window server never
/// starts a window move from there and every press reaches our views. Tabs then
/// get their own drags, and empty chrome moves the window through
/// `WindowDragRegionView`. macOS 27 decides title-bar drags this way and ignores
/// `mouseDownCanMoveWindow`.
///
/// SwiftUI owns the content view, so the method goes on its class at runtime,
/// answering for claimed windows only; other windows sharing that class (Settings)
/// keep AppKit's behavior.
enum TitlebarDragOwnership {
    private static let claimed = NSHashTable<NSWindow>.weakObjects()
    private static var patched: Set<ObjectIdentifier> = []
    private static let selector = NSSelectorFromString("_opaqueRectForWindowMoveWhenInTitlebar")

    static func claim(_ window: NSWindow) {
        guard let content = window.contentView else { return }
        claimed.add(window)
        let cls: AnyClass = type(of: content)
        guard patched.insert(ObjectIdentifier(cls)).inserted else { return }

        typealias Original = @convention(c) (NSView, Selector) -> NSRect
        let original = class_getInstanceMethod(cls, selector).map {
            unsafeBitCast(method_getImplementation($0), to: Original.self)
        }
        let replacement: @convention(block) (NSView) -> NSRect = { view in
            if let window = view.window, claimed.contains(window), view === window.contentView {
                return view.bounds
            }
            return original?(view, selector) ?? .zero
        }
        let types = class_getInstanceMethod(cls, selector).flatMap { method_getTypeEncoding($0) }
            .map { String(cString: $0) } ?? "{CGRect={CGPoint=dd}{CGSize=dd}}@:"
        class_replaceMethod(cls, selector, imp_implementationWithBlock(replacement), types)
    }
}

/// Place this only in the empty toolbar space (e.g. after tabs and + button).
/// Dragging from here moves the window; dragging from tabs reorders tabs.
struct WindowDragRegionView: NSViewRepresentable {
    func makeNSView(context: Context) -> NSView { WindowDragRegionNSView() }
    func updateNSView(_ nsView: NSView, context: Context) {}
}

/// Configures the window for a Chrome/Dia-style titlebar:
/// - titlebar is transparent so we can paint over it
/// - title text is hidden
/// - titlebar height is enlarged to fit the tab strip
///
/// The `tabStripHeight` parameter tells us how tall our tab strip is so we
/// can match the titlebar to it exactly.
struct TitlebarConfigurator: NSViewRepresentable {
    let tabStripHeight: CGFloat
    @Binding var isFullScreen: Bool
    @Binding var hostWindow: NSWindow?

    func makeCoordinator() -> Coordinator { Coordinator(self) }

    func makeNSView(context: Context) -> NSView {
        let view = NSView()
        DispatchQueue.main.async {
            guard let window = view.window else { return }
            self.hostWindow = window
            window.titlebarAppearsTransparent = true
            window.titleVisibility = .hidden
            window.styleMask.insert(.fullSizeContentView)
            window.isMovableByWindowBackground = false
            window.tabbingMode = .disallowed
            TitlebarDragOwnership.claim(window)

            context.coordinator.isFullScreen = window.styleMask.contains(.fullScreen)
            if context.coordinator.isFullScreen { Coordinator.setFullScreenTitlebarHidden(true, in: window) }

            NotificationCenter.default.addObserver(
                context.coordinator,
                selector: #selector(Coordinator.didEnterFullScreen),
                name: NSWindow.didEnterFullScreenNotification,
                object: window
            )
            NotificationCenter.default.addObserver(
                context.coordinator,
                selector: #selector(Coordinator.didExitFullScreen),
                name: NSWindow.didExitFullScreenNotification,
                object: window
            )
            NotificationCenter.default.addObserver(
                context.coordinator,
                selector: #selector(Coordinator.willExitFullScreen),
                name: NSWindow.willExitFullScreenNotification,
                object: window
            )
        }
        return view
    }

    func updateNSView(_ nsView: NSView, context: Context) {}

    static func dismantleNSView(_ nsView: NSView, coordinator: Coordinator) {
        NotificationCenter.default.removeObserver(coordinator)
    }

    class Coordinator: NSObject {
        var parent: TitlebarConfigurator

        var isFullScreen: Bool {
            get { parent.isFullScreen }
            set { parent.isFullScreen = newValue }
        }

        init(_ parent: TitlebarConfigurator) {
            self.parent = parent
        }

        nonisolated deinit {
            NotificationCenter.default.removeObserver(self)
        }

        @objc func didEnterFullScreen(_ note: Notification) {
            if let window = note.object as? NSWindow { Self.setFullScreenTitlebarHidden(true, in: window) }
            DispatchQueue.main.async { self.isFullScreen = true }
        }

        @objc func willExitFullScreen(_ note: Notification) {
            if let window = note.object as? NSWindow { Self.setFullScreenTitlebarHidden(false, in: window) }
        }

        /// In full screen macOS slides the window's titlebar down over the content when the
        /// pointer reaches the top: an opaque strip with the window buttons that covers Luna's
        /// tab row. Luna draws its own tab row, so the titlebar stays hidden in full screen and
        /// the top edge reveals only the menu bar, as in Chrome. Restored before leaving full screen.
        static func setFullScreenTitlebarHidden(_ hidden: Bool, in window: NSWindow) {
            // close button → NSTitlebarView → NSTitlebarContainerView
            guard let container = window.standardWindowButton(.closeButton)?.superview?.superview,
                  container !== window.contentView else { return }
            container.isHidden = hidden
        }

        @objc func didExitFullScreen(_ note: Notification) {
            if let window = note.object as? NSWindow { Self.setFullScreenTitlebarHidden(false, in: window) }
            DispatchQueue.main.async { self.isFullScreen = false }
        }
    }
}

